INSERT INTO `wp_aioseo_notifications` (`id`, `slug`, `addon`, `title`, `content`, `type`, `level`, `notification_id`, `notification_name`, `start`, `end`, `button1_label`, `button1_action`, `button2_label`, `button2_action`, `dismissed`, `new`, `created`, `updated`) VALUES
(1, '632d03430bde6', NULL, '? Our fall sale is on! ?', 'Get up to 70% off AIOSEO Pro to improve your SEO rankings.\r\n<br><br>\r\nThis will get you access to our Next-Gen Schema generator, powerful Link Assistant, and dozens of SEO features to grow your traffic.\r\n<br><br>\r\nUpgrade this week and save BIG!', 'success', '[\"4-x\",\"lite\"]', 503, NULL, '2022-09-22 20:05:34', '2022-09-29 00:00:00', 'Get AIOSEO Pro NOW! (70% OFF)', 'https://aioseo.com/pricing-lite/?utm_source=WordPress&utm_campaign=2022-fall-sale-v4-lite&utm_medium=plugin-notification&utm_content=Get AIOSEO Pro NOW! (70% OFF)', NULL, NULL, 0, 0, '2022-09-23 00:52:19', '2022-09-26 03:44:12'),
(2, '632d03430dc07', NULL, 'AIOSEO just got more powerful with version 4.2.4! ?', 'Easily eliminate 404 errors with <strong>automatic redirects</strong> using our massively improved Redirection Manager. \r\n<br><br>\r\nThis update also includes some huge improvements to our Image SEO addon, making it much easier for your content to rank. ?\r\n<br><br>\r\nUpdate to <strong>AIOSEO 4.2.4</strong> today and take advantage of these powerful new features!', 'success', '[\"4-x\",\"lite\"]', 463, NULL, '2022-09-22 20:05:34', NULL, 'Learn More', 'https://aioseo.com/announcing-aioseo-4-2-4-improved-redirects-and-image-seo-updates/?utm_source=WordPress&utm_campaign=improved-redirects-image-seo-v4-lite&utm_medium=plugin-notification&utm_content=Learn More', 'Get AIOSEO Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=improved-redirects-image-seo-v4-lite&utm_medium=plugin-notification&utm_content=Get%20AIOSEO%20Pro', 0, 0, '2022-09-23 00:52:19', '2022-10-08 12:11:25'),
(3, '6351c71191a49', NULL, 'The much-awaited SEO emoji picker is here! ?', 'Now you can add emojis to SEO fields to get <strong>higher CTRs and engagement on SEO and social media platforms</strong>. ?\r\n<br><br>\r\nPlus, we’ve also greatly improved our multisite SEO module, making it easy to <strong>manage WordPress multisite SEO from a single dashboard</strong>. ✅\r\n<br><br>\r\nWith AIOSEO 4.2.6, you’ve got more tools to help you rank your content, and that <strong>without touching a single line of code</strong>. ??‍?\r\n<br><br>\r\n<strong>Update to AIOSEO 4.2.6 TODAY</strong> and enjoy the power of our new SEO emoji picker and improved multisite SEO module! ?', 'success', '[\"4-x\",\"lite\"]', 512, NULL, '2022-11-28 20:45:42', NULL, 'Learn More', 'https://aioseo.com/announcing-aioseo-4-2-6-new-seo-emoji-picker-multisite-seo-improvements/?utm_source=WordPress&utm_campaign=emoji-picker-v4-lite&utm_medium=plugin-notification&utm_content=Learn More', '? Get AIOSEO Pro NOW!', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=emoji-picker-v4-lite&utm_medium=plugin-notification&utm_content=? Get AIOSEO Pro NOW!', 0, 0, '2022-10-20 22:09:21', '2022-12-05 01:31:46'),
(4, '636bf9ed075f7', NULL, 'Announcing AIOSEO 4.2.7: Google Merchant Center Schema to help you Boost Visibility and Sales! ??', 'Do you sell products on your website? We’ve got great news for you!\r\n<br><br>\r\nEnjoy greater visibility and higher CTRs for your products on search engines with our new <strong>Google Merchant Center</strong> Listing schema support. \r\n<br><br>\r\nSo, go ahead and upgrade to <strong>AIOSEO Pro 4.2.7 TODAY</strong> and get more tools to help you rank your content and products!', 'success', '[\"4-x\",\"lite\"]', 526, NULL, '2022-12-06 20:35:55', NULL, 'Learn More', 'https://aioseo.com/announcing-aioseo-4-2-7-drive-more-sales-with-google-merchant-center-listing-schema/?utm_source=WordPress&utm_campaign=google-merchant-center-schema-v4-lite&utm_medium=plugin-notification&utm_content=Learn More', 'Get AIOSEO Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=google-merchant-center-schema-v4-lite&utm_medium=plugin-notification&utm_content=Get AIOSEO Pro', 0, 0, '2022-11-09 19:05:17', '2023-02-07 17:46:20'),
(5, '637ba3702e076', NULL, 'Black Friday: HUGE Sale! Get Up to 70% Off AIOSEO ?', 'Our biggest sale of the year is now live! Get up to 70% off AIOSEO, the world’s best WordPress SEO plugin. You’ll unlock our NEW Link Assistant addon, redirection manager, local SEO module, image SEO module, news/video sitemaps +more! PLUS enter our giveaway to WIN an Apple 14” M1 PRO Macbook Pro - no purchase necessary!', 'success', '[\"4-x\",\"lite\"]', 534, NULL, '2022-11-24 19:50:33', '2022-11-28 00:00:00', 'Enter Giveaway', 'https://aioseo.com/black-friday/?utm_source=WordPress&utm_campaign=liteplugin&utm_medium=Plugin Notification&utm_content=bf2022-enter-giveaway-v4-lite', 'Claim Your Upgrade Discount', 'https://aioseo.com/black-friday/?utm_source=WordPress&utm_campaign=liteplugin&utm_medium=Plugin Notification&utm_content=bf2022-claim-your-upgrade-discount-v4-lite', 0, 0, '2022-11-21 16:12:32', '2022-11-25 22:50:27'),
(6, '63921a68ca374', NULL, 'AIOSEO 4.2.8: More Control Over Search and Social Snippets with SEO Preview ?', 'Get greater control over how your search and social media snippets appear with our <strong>new SEO Preview tool</strong>.\r\n<br><br>\r\nPlus, check how well you’ve set up your page’s SEO by getting an overview of your meta tags and basic SEO.\r\n<br><br>\r\nSo, <strong>update to AIOSEO 4.2.8 TODAY</strong> and boost your rankings and drive more engagement on SERPs and social media!', 'success', '[\"4-x\",\"lite\"]', 560, NULL, '2023-02-24 16:13:04', NULL, 'Learn More', 'https://aioseo.com/new-seo-preview-more-control-over-search-and-social-snippets/?utm_source=WordPress&utm_campaign=seo-preview-v4-lite&utm_medium=plugin-notification&utm_content=Learn More', 'Get AIOSEO Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=seo-preview-v4-lite&utm_medium=plugin-notification&utm_content=Get AIOSEO Pro', 0, 0, '2022-12-08 17:10:00', '2023-03-08 17:46:45'),
(7, '63e41809a9adb', NULL, 'Introducing SEO Stats for WordPress - Track Your Keyword Rankings and See Important SEO Metrics with 1-click ? ?', 'Want to see exactly how your content ranks in search results inside of WordPress? You can do just that with our brand new <strong>Google Search Console integration</strong>!\r\n<br><br>\r\nTrack important keywords and get in-plugin tips to help you grow your traffic. <strong>Plus: Try out the new speed test tool!</strong> ?\r\n<br><br>\r\n<strong>Upgrade to AIOSEO 4.3.0 (Elite) TODAY to ignite your SEO and outrank competitors!</strong>\r\n<br><br>\r\n<img src=\"data:image/png;base64,\" />', 'success', '[\"4-x\",\"lite\"]', 570, NULL, '2023-06-27 12:55:16', NULL, 'Learn More', 'https://aioseo.com/google-search-console-integration/?utm_source=WordPress&utm_campaign=google-search-console-integration-v4-lite&utm_medium=plugin-notification&utm_content=Learn%20More', 'Get AIOSEO Pro ?', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=google-search-console-integration-v4-lite&utm_medium=plugin-notification&utm_content=Get%20AIOSEO%20Pro', 0, 0, '2023-02-08 21:45:45', '2023-07-01 21:14:51'),
(8, '63fb2b29a9f34', NULL, '❄️ Save up to 70% OFF Link Assistant, Search Statistics and MORE During our Winter Sale! ❄️', 'We’re kicking off our winter sale and you don’t want to miss the hot deals we have. ?\r\n<br><br>\r\nIf you act within the next 7 days, you can get AIOSEO <strong>for as much as 70% off</strong> with access to our <strong>Redirection Manager, Link Assistant, Search Statistics and MORE</strong>!\r\n<br><br>\r\nWith all the powerful features we’ll be adding to the plugin this year, getting the plugin at these discounted prices is a steal. <strong>Seriously</strong>.\r\n<br><br>\r\n⚡ So, claim your discount now before it expires! ⚡', 'success', '[\"4-x\",\"lite\"]', 603, NULL, '2023-02-24 16:13:04', '2023-03-02 00:00:00', 'Get AIOSEO Pro Today! (up to 70% OFF)', 'https://aioseo.com/pricing-lite/?utm_source=WordPress&utm_campaign=proplugin&utm_medium=Plugin%20Notification&utm_content=winter-sale-2023-get-aioseo-pro-today', NULL, NULL, 0, 0, '2023-02-26 09:49:29', '2023-03-01 00:02:19'),
(9, '641575143dd6b', NULL, '?[FLASH SALE]! Get Up To 70% Off AIOSEO For St. Patrick\'s Day! ?', 'Our St. Patrick\'s Day flash sale is here, and it\'s your chance to get <strong>AIOSEO Pro at a HUGE discount</strong>! This sale is almost as good as a pot of gold!\r\n<br><br>\r\nDon\'t rely only on the luck of the Irish! ☘️ Supercharge your website\'s SEO, making it easier for your customers to find you online. With our limited-time offer, you can get the whole AIOSEO experience at up to 70% off!\r\n<br><br>\r\nWhether you\'re a small business owner, blogger, or marketer, this is an opportunity you won\'t want to miss. Hurry and grab your discount now before the sale ends!', 'success', '[\"4-x\",\"lite\"]', 636, NULL, '2023-03-17 02:11:24', '2023-03-19 00:00:00', 'Get AIOSEO Pro Today!', 'https://aioseo.com/pricing/?utm_source=WordPress&utm_campaign=v4-lite&utm_medium=Plugin%20Notification&utm_content=st-patricks-2023-get-aioseo-pro-today', NULL, NULL, 0, 0, '2023-03-18 08:23:48', '2023-03-18 08:23:48'),
(10, '6442eceae87d0', NULL, '[Last Chance!] ? Save up to 70% on AIOSEO during our spring sale! ?', 'Did you know today\'s the last day to <strong>upgrade</strong> and <strong>save big</strong> on the world\'s best SEO plugin?\r\n<br><br>\r\n⚡ Power up your traffic & sales with our futuristic <strong>AI tools</strong> and <strong>Google Search Console integration</strong>. \r\n<br><br>\r\nDon’t miss out on these amazing deals. ?\r\n<br><br>\r\nBe sure to claim your discount before it\'s gone!', 'success', '[\"4-x\",\"lite\"]', 661, NULL, '2023-04-27 00:00:00', '2023-04-28 00:00:00', 'Get AIOSEO Pro Today!', 'https://aioseo.com/pricing-lite/?utm_source=WordPress&utm_campaign=v4-lite&utm_medium=Plugin%20Notification&utm_content=spring-sale-last-chance-2023-get-aioseo-pro-today', NULL, NULL, 0, 0, '2023-04-21 20:07:06', '2023-04-25 19:32:41'),
(11, '6442eceaeb235', NULL, '[Spring Sale] ? Get up to 70% off AIOSEO! ?', 'We just launched our huge spring sale. Now you can get <strong><em>all</em></strong> the SEO features you want to amplify your traffic and sales. \r\n<ul style=\"list-style: inside;\">\r\n	<li>Supercharge your <strong>keyword rankings</strong> with our <strong>Google Search Console integration</strong>.</li>\r\n	<li>Save time with our premier <strong>AI tools</strong>, like our <strong>ChatGPT integration</strong>.</li>\r\n</ul>\r\nFor only 7 days you can get <strong>deep discounts</strong> on the world\'s best SEO plugin.\r\n<br><br>\r\n⚡So grab your deal while it lasts! ⚡', 'success', '[\"4-x\",\"lite\"]', 651, NULL, '2023-04-21 16:17:02', '2023-04-27 00:00:00', 'Get AIOSEO Pro Today!', 'https://aioseo.com/pricing-lite/?utm_source=WordPress&utm_campaign=v4-lite&utm_medium=Plugin%20Notification&utm_content=spring-sale-2023-get-aioseo-pro-today', NULL, NULL, 0, 0, '2023-04-21 20:07:06', '2023-04-25 19:32:41'),
(12, '6453606088f9c', NULL, '?️ [AIOSEO 4.3.6] Announcing Content Rankings: SEO Performance Tracking Made Easy', 'Get valuable insights about how your content is performing on search engines using our <strong>NEW Content Rankings report</strong>.\r\n<br><br>\r\nThis includes SEO data to help you <strong>optimize your articles for better rankings</strong>. Plus, you can also easily spot <strong>content decay</strong>, making it easier to combat it.\r\n<br><br>\r\nSo, <strong>upgrade to AIOSEO Pro TODAY</strong> and boost your rankings and drive more traffic to your content!', 'success', '[\"4-x\",\"lite\"]', 677, NULL, '2023-06-27 12:55:16', NULL, 'Learn More', 'https://aioseo.com/announcing-content-rankings-seo-performance-tracking-made-easy/?utm_source=WordPress&utm_campaign=content-rankings-v4-lite&utm_medium=plugin-notification&utm_content=Learn%20More', 'Get AIOSEO Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=content-rankings-v4-lite&utm_medium=plugin-notification&utm_content=Get%20AIOSEO%20Pro', 0, 0, '2023-05-04 07:36:00', '2023-07-01 21:14:51'),
(13, '647561272ca6c', NULL, '[Last Chance!] ?? Save up to 70% on AIOSEO during our flash sale! ?', 'Did you know today\'s the <span style=\"text-decoration:underline;\">last day</span> to <strong>upgrade</strong> & <strong>save big</strong> on the world\'s best SEO plugin?\r\n<br><br>\r\n⚡ Power up your traffic & sales with our futuristic <strong>AI tools</strong> & <strong>Google Search Console integration</strong>. ⚡\r\n<br><br>\r\nDon’t miss out on these sizzling deals. ?\r\n<br><br>\r\nClaim your discount before it\'s gone!', 'success', '[\"4-x\",\"lite\"]', 721, NULL, '2023-05-30 00:00:00', '2023-05-31 00:00:00', 'Get AIOSEO Pro Today!', 'https://aioseo.com/pricing-lite/?utm_source=WordPress&utm_campaign=v4-lite&utm_medium=Plugin%20Notification&utm_content=memorial-day-sale-last-chance-2023-get-aioseo-pro-today', NULL, NULL, 0, 0, '2023-05-30 02:36:23', '2023-05-30 02:36:23'),
(14, '647561272ee79', NULL, '[Memorial Day Sale] ?? Get up to 70% off AIOSEO! ?', 'We just launched our Memorial Day sale! Snag <strong style=\"text-decoration: underline;\"><em>all</em></strong> the SEO features you want to surge traffic and sales. \r\n<ul style=\"list-style: inside;\">\r\n	<li>Save time with our AI <strong>ChatGPT integration</strong>.</li>\r\n	<li>Boost <strong>rankings</strong> with our <strong>Google Search Console integration</strong>.</li>\r\n</ul>\r\nFor only <strong style=\"text-decoration: underline;\">1 day</strong> you can get <strong>giant discounts</strong> on the world\'s best SEO plugin.\r\n<br /><br />\r\n⚡So grab your deal while it lasts! ⚡', 'success', '[\"4-x\",\"lite\"]', 708, NULL, '2023-05-29 13:43:06', NULL, 'Get AIOSEO Pro Today!', 'https://aioseo.com/pricing-lite/?utm_source=WordPress&utm_campaign=v4-lite&utm_medium=Plugin%20Notification&utm_content=memorial-day-sale-2023-get-aioseo-pro-today', NULL, NULL, 0, 0, '2023-05-30 02:36:23', '2023-05-31 10:29:13'),
(15, '6478cfca5ab91', NULL, '[NEW] Set a Primary Category to Customize Breadcrumbs (+ WPCode Integration) ?', '<strong>The wait is FINALLY over!</strong> One of our most requested feature is live in AIOSEO 4.3.8! ? ?\r\n<br><br>\r\nWith the brand-new <strong>Primary Category</strong> feature, you now have <strong>full control over which category displays in your breadcrumb trail</strong>.\r\n<br><br>\r\nPlus: customize your AIOSEO experience with <strong>clickable code snippets</strong> courtesy of WPCode!\r\n<br><br>\r\nUpgrade to <strong>AIOSEO 4.3.8 Pro TODAY</strong> to ignite your SEO and outrank competitors!', 'success', '[\"4-x\",\"lite\"]', 751, NULL, '2023-07-25 13:50:35', NULL, 'Learn More', 'https://aioseo.com/announcing-primary-category-and-wpcode-integration/?utm_source=WordPress&utm_campaign=primary-category-v4-lite&utm_medium=plugin-notification&utm_content=Learn%20More', 'Get AIOSEO Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=primary-category-v4-lite&utm_medium=plugin-notification&utm_content=Get%20AIOSEO%20Pro', 0, 0, '2023-06-01 17:05:14', '2023-07-27 19:21:01'),
(16, '649b5bd9775ac', NULL, 'It\'s a Sweet Sixteen Kinda Day! ? ?', '<img src=\"data:image/png;base64,\" />\r\n\r\nWe just had our 16th birthday, and to celebrate, we’re offering you massive discounts on all paid plans. Save <strong>up to 70%</strong> when you purchase a new plan or upgrade TODAY!\r\n<br><br>\r\nPlus, we have a <strong>sweet giveaway</strong> with 3 prizes including a <strong>Pixel 7 Pro, Pixel Tablet and Pixel Buds Pro</strong>!\r\n<br><br>\r\nHurry, this deal won\'t last long, check it out TODAY!', 'success', '[\"4-x\",\"lite\"]', 766, NULL, '2023-06-27 12:55:16', '2023-06-30 00:00:00', 'Get AIOSEO Pro NOW! (70% OFF)', 'https://aioseo.com/happy-birthday-aioseo/?utm_source=WordPress&utm_campaign=16th-birthday-sale-v4-lite&utm_medium=plugin-notification&utm_content=Get AIOSEO Pro NOW! (70% OFF)', 'Enter Pixel Giveaway!', 'https://aioseo.com/happy-birthday-aioseo/?utm_source=WordPress&utm_campaign=16th-birthday-sale-v4-lite&utm_medium=plugin-notification&utm_content=Enter Pixel Giveaway!', 0, 0, '2023-06-27 21:59:53', '2023-06-29 08:25:26'),
(17, '64a37c6e57444', NULL, '? [New] Advanced SEO Tracking with SEO Revisions & Google Updates Integration', 'Track the changes you make to your content and see how it <strong>connects to changes in your search rankings</strong>.\r\n<br><br>\r\nPlus, see <strong>Google Updates on a timeline in Search Statistics</strong>, so you know how they impact your SEO.\r\n<br><br>\r\nWe’ve also added many more new features to version 4.4.0 of AIOSEO. <strong>Upgrade today!</strong>', 'success', '[\"4-x\",\"lite\"]', 801, NULL, '2023-09-19 21:26:06', NULL, 'Learn More', 'https://aioseo.com/announcing-seo-revisions-and-google-updates-integration/?utm_source=WordPress&utm_campaign=seo-revisions-v4-lite&utm_medium=plugin-notification&utm_content=Learn%20More', 'Get AIOSEO Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=seo-revisions-v4-lite&utm_medium=plugin-notification&utm_content=Get%20AIOSEO%20Pro', 0, 0, '2023-07-04 01:57:02', '2023-10-15 17:17:40'),
(18, '64bfed11906b5', NULL, 'NEW: Announcing the AIOSEO Analyzer Chrome extension!  ?', 'Speed up content reviews and technical SEO checks. This new free tool is designed for you!\r\n<br><br>\r\nAIOSEO Analyzer gives you a big-picture view of your SEO, bringing problem areas into sharp focus. It works on both unpublished <em>and</em> published pages.\r\n<br><br>\r\nAnd it’s <strong>100% free!</strong> Download it today from the Chrome Web Store. And take it for a test drive!', 'success', '[\"4-x\"]', 809, NULL, '2023-11-25 04:17:13', NULL, 'Learn More', 'https://aioseo.com/announcing-all-in-one-analyzer-by-aioseo/?utm_source=WordPress&utm_campaign=chrome-extension-v4&utm_medium=plugin-notification&utm_content=Learn%20More', 'Download', 'https://aioseo.com/announcing-all-in-one-analyzer-by-aioseo/?utm_source=WordPress&utm_campaign=chrome-extension-v4&utm_medium=plugin-notification&utm_content=Download', 0, 0, '2023-07-25 15:41:05', '2023-12-05 02:30:15'),
(19, '64c42a600e0fe', NULL, '?? Embrace the summer vibes with our scorching HOT Summer Sale! ??', '<img src=\"data:image/png;base64,\" />\r\n\r\nIt\'s time to turn up the heat and celebrate the season in style. Whether you\'re a long-time user or a brand-new one, we\'ve got something special for you!\r\n<br><br>\r\nIn honor of summer, we\'re offering you sensational discounts on all paid plans. Save up to a refreshing 70% when you snag a new plan or upgrade TODAY!\r\n<br><br>\r\nBut don\'t lounge around too long under the sun – this irresistible offer won\'t last forever! So, hurry and dive into our Summer Sale before it\'s gone. Your special deal awaits!\r\n', 'success', '[\"4-x\",\"lite\"]', 827, NULL, '2023-07-28 18:10:46', '2023-08-04 00:00:00', 'Get AIOSEO Pro NOW! (70% OFF)', 'https://aioseo.com/pricing-lite/?utm_source=WordPress&utm_campaign=summer-sale-v4-lite&utm_medium=plugin-notification&utm_content=Upgrade Your AIOSEO Plan NOW! (70% OFF)', NULL, NULL, 0, 0, '2023-07-28 20:51:44', '2023-08-03 08:25:06'),
(20, '64ebe081b2775', NULL, '[New] Improved Crawling and Indexing with AIOSEO 4.4.4 ?', 'Improve your site’s crawlability and indexability with our improved robots.txt editor. With new directives and advanced functionality, ranking your site on search engines just became easier.\r\n<br><br>\r\nWe’ve also added many more new features to version 4.4.4 of AIOSEO. Check out our announcement for more information.\r\n<br><br>\r\nUpgrade to AIOSEO 4.4.4 today!', 'success', '[\"4-x\",\"lite\"]', 832, NULL, '2023-11-25 04:17:13', NULL, 'Learn More', 'https://aioseo.com/greater-robots-txt-file-customization-for-improved-crawlability/?utm_source=WordPress&utm_campaign=robots-editor-v4-lite&utm_medium=plugin-notification&utm_content=Learn%20More', 'Upgrade to Pro', 'https://aioseo.com/lite-upgrade/?utm_source=WordPress&utm_campaign=robots-editor-v4-lite&utm_medium=plugin-notification&utm_content=Upgrade%20to%20Pro', 0, 0, '2023-08-27 23:47:13', '2023-12-05 02:30:15'),
(21, '64f772d05a78b', NULL, 'Flash Sale: Get Up To 70% Off AIOSEO This Labor Day ?', 'At AIOSEO, we want to celebrate your hard work by offering you the best WordPress SEO plugin at <strong><em>ridiculously low prices</em></strong>.\r\n<br><br>\r\nWe’re offering <strong>up to 70% off</strong> AIOSEO for a new purchase or upgrade.\r\n<br><br>\r\nBut this is just a one-day sale, so you better ACT FAST!', 'success', '[\"lite\"]', 840, NULL, '2023-09-04 21:39:37', '2023-09-06 00:00:00', 'Get AIOSEO Pro NOW! (70% OFF)', 'https://aioseo.com/pricing-lite/?utm_source=WordPress&utm_campaign=summer-sale-v4-lite&utm_medium=plugin-notification&utm_content=Get AIOSEO Pro NOW! (70% OFF)', NULL, NULL, 0, 0, '2023-09-05 18:26:24', '2023-09-05 18:26:24');
